#!/usr/bin/env python3
"""
Generate per-session reports and dashboard from master index.
"""

import json, os, re
from datetime import datetime
from collections import Counter

OUTPUT_DIR = r'X:\SESSION_ARCHIVES\ALL_SESSIONS_DIRECTORY_VAULT\session_reports'
INDEX_PATH = os.path.join(OUTPUT_DIR, 'MASTER_INDEX.json')

with open(INDEX_PATH, 'r', encoding='utf-8') as f:
    all_sessions = json.load(f)

# ============================================================
# GENERATE PER-SESSION REPORTS (for significant sessions)
# ============================================================
significant_sessions = [s for s in all_sessions if s['status'] in ('Completed', 'Partial', 'Ongoing')]
print(f"Generating reports for {len(significant_sessions)} significant sessions...")

for session in significant_sessions[:200]:  # Top 200
    tool = session['tool']
    sid = session['id']
    title = session['title']
    safe_sid = re.sub(r'[^a-zA-Z0-9_-]', '_', sid)
    report_path = os.path.join(OUTPUT_DIR, f'{tool}-{safe_sid}.md')

    report = f"""# Session Report: {title}

## Metadata
- **ID**: {sid}
- **Tool**: {tool}
- **Date**: {session.get('date', 'Unknown')}
- **Status**: {session.get('status', 'Unknown')}
- **Turns**: {session.get('turns_user', 0)} user / {session.get('turns_assistant', 0)} assistant

## Summary
{session.get('summary', 'No summary available.')}

## Full Prompt / Objective
{session.get('full_prompt', 'N/A')}

## Status Assessment
{session.get('status', 'Unknown')} - {session.get('recommendations', 'No recommendations.')}

## Recommendations
- {session.get('recommendations', 'Review session artifacts and document outcomes.')}

## Tags
{tool}, {session.get('status', 'unknown')}
"""

    with open(report_path, 'w', encoding='utf-8') as f:
        f.write(report)

print(f"Generated {min(len(significant_sessions), 200)} session reports")

# ============================================================
# GENERATE MASTER INDEX MARKDOWN
# ============================================================
print("Generating MASTER_INDEX.md...")

by_tool = Counter(s['tool'] for s in all_sessions)
by_status = Counter(s['status'] for s in all_sessions)
by_date = Counter(s['date'] for s in all_sessions if s['date'] != 'Unknown')

total_turns_user = sum(s.get('turns_user', 0) for s in all_sessions)
total_turns_assistant = sum(s.get('turns_assistant', 0) for s in all_sessions)

md = f"""# Master Session Index

**Generated**: {datetime.now().strftime('%Y-%m-%d %H:%M')}
**Total Sessions**: {len(all_sessions)}
**Total Turns**: {total_turns_user} user / {total_turns_assistant} assistant

## Statistics

### By Tool
| Tool | Sessions | % |
|------|----------|---|
"""
for tool, count in sorted(by_tool.items(), key=lambda x: -x[1]):
    pct = count / len(all_sessions) * 100
    md += f"| {tool} | {count} | {pct:.1f}% |\n"

md += f"""
### By Status
| Status | Count | % |
|--------|-------|---|
"""
for status, count in sorted(by_status.items(), key=lambda x: -x[1]):
    pct = count / len(all_sessions) * 100
    md += f"| {status} | {count} | {pct:.1f}% |\n"

md += f"""
### Date Range
- **Start**: {min(by_date.keys()) if by_date else 'N/A'}
- **End**: {max(by_date.keys()) if by_date else 'N/A'}
- **Most Active**: {sorted(by_date.items(), key=lambda x: -x[1])[0][0] if by_date else 'N/A'} ({sorted(by_date.items(), key=lambda x: -x[1])[0][1] if by_date else 0} sessions)

## Sessions by Tool

"""
for tool in sorted(by_tool.keys()):
    sessions = [s for s in all_sessions if s['tool'] == tool]
    md += f"### {tool} ({len(sessions)} sessions)\n\n"
    md += "| ID | Date | Title | Status | Turns |\n"
    md += "|-----|------|-------|--------|-------|\n"
    for s in sessions[:50]:
        md += f"| {s['id'][:12]} | {s.get('date','?')[:10]} | {s['title'][:60]} | {s.get('status','?')} | {s.get('turns_user',0)}u/{s.get('turns_assistant',0)}a |\n"
    if len(sessions) > 50:
        md += f"\n... and {len(sessions)-50} more sessions\n"
    md += "\n"

with open(os.path.join(OUTPUT_DIR, 'MASTER_INDEX.md'), 'w', encoding='utf-8') as f:
    f.write(md)
print("Generated MASTER_INDEX.md")

# ============================================================
# GENERATE INTERACTIVE DASHBOARD
# ============================================================
print("Generating DASHBOARD.html...")

# Prepare data for JS
sessions_js = json.dumps(all_sessions, ensure_ascii=False)

dashboard_html = f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>AI Session Dashboard</title>
<style>
* {{ margin: 0; padding: 0; box-sizing: border-box; }}
body {{
  font-family: 'Segoe UI', system-ui, sans-serif;
  background: #0f0f1a;
  color: #e0e0e0;
  min-height: 100vh;
}}
.header {{
  background: linear-gradient(135deg, #1a1a2e 0%, #16213e 100%);
  padding: 24px;
  border-bottom: 1px solid #2a2a4a;
}}
.header h1 {{
  font-size: 28px;
  font-weight: 700;
  background: linear-gradient(90deg, #00d4ff, #7b2fff);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  margin-bottom: 8px;
}}
.header p {{ color: #888; font-size: 14px; }}
.stats-grid {{
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 16px;
  padding: 24px;
}}
.stat-card {{
  background: #1a1a2e;
  border: 1px solid #2a2a4a;
  border-radius: 12px;
  padding: 20px;
  text-align: center;
  transition: transform 0.2s;
}}
.stat-card:hover {{ transform: translateY(-2px); }}
.stat-value {{
  font-size: 32px;
  font-weight: 700;
  background: linear-gradient(90deg, #00d4ff, #7b2fff);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}}
.stat-label {{
  color: #888;
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 1px;
  margin-top: 4px;
}}
.controls {{
  padding: 0 24px 24px;
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
  align-items: center;
}}
.controls input, .controls select {{
  background: #1a1a2e;
  border: 1px solid #2a2a4a;
  color: #e0e0e0;
  padding: 10px 16px;
  border-radius: 8px;
  font-size: 14px;
}}
.controls input {{ flex: 1; min-width: 200px; }}
.filter-btn {{
  background: #2a2a4a;
  border: 1px solid #3a3a5a;
  color: #e0e0e0;
  padding: 8px 16px;
  border-radius: 6px;
  cursor: pointer;
  font-size: 13px;
  transition: all 0.2s;
}}
.filter-btn:hover {{ background: #3a3a5a; }}
.filter-btn.active {{ background: #7b2fff; border-color: #7b2fff; }}
.table-container {{
  padding: 0 24px 24px;
  overflow-x: auto;
}}
table {{
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
}}
th {{
  background: #1a1a2e;
  color: #00d4ff;
  padding: 12px;
  text-align: left;
  cursor: pointer;
  border-bottom: 2px solid #2a2a4a;
  white-space: nowrap;
}}
th:hover {{ color: #fff; }}
td {{
  padding: 10px 12px;
  border-bottom: 1px solid #1a1a2e;
  vertical-align: top;
}}
tr:hover {{ background: #1a1a2e; }}
.status-badge {{
  display: inline-block;
  padding: 4px 8px;
  border-radius: 4px;
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
}}
.status-completed {{ background: #1a3a2a; color: #4ade80; }}
.status-partial {{ background: #3a3a1a; color: #facc15; }}
.status-abandoned {{ background: #3a1a1a; color: #f87171; }}
.status-ongoing {{ background: #1a2a3a; color: #60a5fa; }}
.tool-tag {{
  display: inline-block;
  padding: 2px 8px;
  border-radius: 4px;
  font-size: 11px;
  background: #2a2a4a;
  color: #aaa;
  margin-right: 4px;
}}
.expand-btn {{
  background: none;
  border: none;
  color: #00d4ff;
  cursor: pointer;
  font-size: 12px;
}}
.expand-btn:hover {{ text-decoration: underline; }}
.detail-row {{ display: none; background: #151525; }}
.detail-row.show {{ display: table-row; }}
.detail-cell {{
  padding: 16px;
  border-bottom: 1px solid #2a2a4a;
}}
.detail-section {{ margin-bottom: 12px; }}
.detail-section h4 {{
  color: #7b2fff;
  font-size: 12px;
  text-transform: uppercase;
  margin-bottom: 4px;
}}
.detail-section p {{ color: #aaa; font-size: 13px; line-height: 1.5; }}
</style>
</head>
<body>
<div class="header">
  <h1>AI Session Dashboard</h1>
  <p>Comprehensive audit across all AI coding tools, IDEs, and agents</p>
</div>

<div class="stats-grid">
  <div class="stat-card">
    <div class="stat-value" id="total-sessions">0</div>
    <div class="stat-label">Total Sessions</div>
  </div>
  <div class="stat-card">
    <div class="stat-value" id="total-tools">0</div>
    <div class="stat-label">Tools</div>
  </div>
  <div class="stat-card">
    <div class="stat-value" id="completed-count">0</div>
    <div class="stat-label">Completed</div>
  </div>
  <div class="stat-card">
    <div class="stat-value" id="partial-count">0</div>
    <div class="stat-label">Partial</div>
  </div>
  <div class="stat-card">
    <div class="stat-value" id="abandoned-count">0</div>
    <div class="stat-label">Abandoned</div>
  </div>
  <div class="stat-card">
    <div class="stat-value" id="total-turns">0</div>
    <div class="stat-label">Total Turns</div>
  </div>
</div>

<div class="controls">
  <input type="text" id="searchInput" placeholder="Search sessions...">
  <select id="toolFilter">
    <option value="all">All Tools</option>
  </select>
  <select id="statusFilter">
    <option value="all">All Status</option>
    <option value="Completed">Completed</option>
    <option value="Partial">Partial</option>
    <option value="Abandoned">Abandoned</option>
    <option value="Ongoing">Ongoing</option>
  </select>
  <button class="filter-btn" onclick="exportCSV()">Export CSV</button>
</div>

<div class="table-container">
  <table id="sessionTable">
    <thead>
      <tr>
        <th onclick="sortBy('id')">ID</th>
        <th onclick="sortBy('tool')">Tool</th>
        <th onclick="sortBy('date')">Date</th>
        <th onclick="sortBy('title')">Title</th>
        <th onclick="sortBy('status')">Status</th>
        <th onclick="sortBy('turns')">Turns</th>
        <th>Actions</th>
      </tr>
    </thead>
    <tbody id="sessionTableBody">
    </tbody>
  </table>
</div>

<script>
const sessions = {sessions_js};
let currentSort = {{ field: 'date', asc: false }};
let filteredSessions = [...sessions];

function init() {{
  // Populate tool filter
  const tools = [...new Set(sessions.map(s => s.tool))].sort();
  const toolFilter = document.getElementById('toolFilter');
  tools.forEach(tool => {{
    const opt = document.createElement('option');
    opt.value = tool;
    opt.textContent = tool;
    toolFilter.appendChild(opt);
  }});

  updateStats();
  renderTable();
}}

function updateStats() {{
  document.getElementById('total-sessions').textContent = sessions.length;
  const tools = new Set(sessions.map(s => s.tool));
  document.getElementById('total-tools').textContent = tools.size;
  document.getElementById('completed-count').textContent = sessions.filter(s => s.status === 'Completed').length;
  document.getElementById('partial-count').textContent = sessions.filter(s => s.status === 'Partial').length;
  document.getElementById('abandoned-count').textContent = sessions.filter(s => s.status === 'Abandoned').length;
  const totalTurns = sessions.reduce((sum, s) => sum + (s.turns_user||0) + (s.turns_assistant||0), 0);
  document.getElementById('total-turns').textContent = totalTurns.toLocaleString();
}}

function renderTable() {{
  const tbody = document.getElementById('sessionTableBody');
  const search = document.getElementById('searchInput').value.toLowerCase();
  const toolFilter = document.getElementById('toolFilter').value;
  const statusFilter = document.getElementById('statusFilter').value;

  filteredSessions = sessions.filter(s => {{
    const matchSearch = !search || 
      s.title.toLowerCase().includes(search) ||
      s.id.toLowerCase().includes(search) ||
      (s.full_prompt && s.full_prompt.toLowerCase().includes(search));
    const matchTool = toolFilter === 'all' || s.tool === toolFilter;
    const matchStatus = statusFilter === 'all' || s.status === statusFilter;
    return matchSearch && matchTool && matchStatus;
  }});

  // Sort
  filteredSessions.sort((a, b) => {{
    let aVal = a[currentSort.field] || '';
    let bVal = b[currentSort.field] || '';
    if (currentSort.field === 'turns') {{
      aVal = (a.turns_user||0) + (a.turns_assistant||0);
      bVal = (b.turns_user||0) + (b.turns_assistant||0);
    }}
    if (aVal < bVal) return currentSort.asc ? -1 : 1;
    if (aVal > bVal) return currentSort.asc ? 1 : -1;
    return 0;
  }});

  tbody.innerHTML = filteredSessions.map((s, i) => {{
    const statusClass = 'status-' + s.status.toLowerCase();
    const dateStr = s.date ? s.date.substring(0, 10) : 'Unknown';
    return `
      <tr>
        <td><code style="color:#666;font-size:11px;">${{s.id.substring(0,12)}}</code></td>
        <td><span class="tool-tag">${{s.tool}}</span></td>
        <td>${{dateStr}}</td>
        <td title="${{escapeHtml(s.title)}}">${{s.title.substring(0, 70)}}${{s.title.length > 70 ? '...' : ''}}</td>
        <td><span class="status-badge ${{statusClass}}">${{s.status}}</span></td>
        <td>${{s.turns_user||0}}u/${{s.turns_assistant||0}}a</td>
        <td>
          <button class="expand-btn" onclick="toggleDetail(${{i}})">Expand</button>
        </td>
      </tr>
      <tr class="detail-row" id="detail-${{i}}">
        <td colspan="7" class="detail-cell">
          <div class="detail-section">
            <h4>Full Prompt</h4>
            <p>${{escapeHtml(s.full_prompt || 'N/A')}}</p>
          </div>
          <div class="detail-section">
            <h4>Summary</h4>
            <p>${{escapeHtml(s.summary || 'No summary')}}</p>
          </div>
          <div class="detail-section">
            <h4>Recommendations</h4>
            <p>${{escapeHtml(s.recommendations || 'No recommendations')}}</p>
          </div>
          ${{s.artifacts && s.artifacts.length > 0 ? `
          <div class="detail-section">
            <h4>Artifacts</h4>
            <p>${{s.artifacts.slice(0, 10).map(a => escapeHtml(a)).join(', ')}}${{s.artifacts.length > 10 ? '...' : ''}}</p>
          </div>
          ` : ''}}
        </td>
      </tr>
    `;
  }}).join('');
}}

function toggleDetail(index) {{
  const row = document.getElementById('detail-' + index);
  row.classList.toggle('show');
}}

function escapeHtml(text) {{
  const div = document.createElement('div');
  div.textContent = text;
  return div.innerHTML;
}}

function sortBy(field) {{
  if (currentSort.field === field) {{
    currentSort.asc = !currentSort.asc;
  }} else {{
    currentSort.field = field;
    currentSort.asc = true;
  }}
  renderTable();
}}

function exportCSV() {{
  let csv = 'ID,Tool,Date,Title,Status,Turns User,Turns Assistant,Recommendations\\n';
  filteredSessions.forEach(s => {{
    csv += `"${{s.id}}","${{s.tool}}","${{s.date}}","${{s.title.replace(/"/g, '""')}}","${{s.status}}",${{s.turns_user||0}},${{s.turns_assistant||0}},"${{(s.recommendations||'').replace(/"/g, '""')}}"\\n`;
  }});
  const blob = new Blob([csv], {{ type: 'text/csv' }});
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = 'session_export.csv';
  a.click();
}}

document.getElementById('searchInput').addEventListener('input', renderTable);
document.getElementById('toolFilter').addEventListener('change', renderTable);
document.getElementById('statusFilter').addEventListener('change', renderTable);

init();
</script>
</body>
</html>"""

with open(os.path.join(OUTPUT_DIR, 'DASHBOARD.html'), 'w', encoding='utf-8') as f:
    f.write(dashboard_html)
print("Generated DASHBOARD.html")

# ============================================================
# GENERATE EXECUTIVE SUMMARY
# ============================================================
print("Generating EXECUTIVE_SUMMARY.md...")

top_tools = by_tool.most_common(10)
top_dates = sorted(by_date.items(), key=lambda x: -x[1])[:10]
top_sessions = sorted(all_sessions, key=lambda s: -(s.get('turns_assistant',0) + s.get('turns_user',0)))[:20]

exec_md = f"""# Executive Summary — All AI Session Audit

**Generated**: {datetime.now().strftime('%Y-%m-%d %H:%M')}
**Total Sessions Audited**: {len(all_sessions)}
**Tools Covered**: {len(by_tool)}
**Date Range**: {min(by_date.keys()) if by_date else 'N/A'} to {max(by_date.keys()) if by_date else 'N/A'}

## Key Findings

### 1. Tool Usage Distribution
"""
for tool, count in top_tools:
    exec_md += f"- **{tool}**: {count} sessions ({count/len(all_sessions)*100:.1f}%)\n"

exec_md += f"""
### 2. Status Breakdown
"""
for status, count in sorted(by_status.items(), key=lambda x: -x[1]):
    exec_md += f"- **{status}**: {count} ({count/len(all_sessions)*100:.1f}%)\n"

exec_md += f"""
### 3. Activity Peaks
"""
for date, count in top_dates:
    exec_md += f"- {date}: {count} sessions\n"

exec_md += f"""
### 4. Most Active Sessions (by turn count)
"""
for s in top_sessions[:10]:
    exec_md += f"- [{s['tool']}] {s['title'][:70]} - {s.get('turns_user',0)}u/{s.get('turns_assistant',0)}a ({s['date']})\n"

exec_md += f"""
### 5. Recurring Themes
- "Review and advise" pattern dominates across all tools
- Crypto trading platform development (multiple attempts)
- Dashboard creation and system integration
- "Proceed all" / automation loops
- Revenue generation and business valuation focus
- Multi-agent orchestration (FOOTCLAN, AI Army)
- Hardware optimization (RTX 4060 8GB)
- Music video / media generation pipelines

### 6. Data Gaps & Limitations
- Charm Crush: 1325 sessions but limited metadata extraction
- Gemini: 76 DB files but protobuf content not fully decoded
- OpenCode: Workspace files found but prompt history not extracted
- Qwen/FreeBuff: 111 log files but format requires specialized parsing
- Claude: 745 history entries but only first 100 processed

### 7. Recommendations
1. **Consolidate**: Merge duplicate sessions across tools into unified project timelines
2. **Extract**: Deep-parse Charm Crush and Gemini DBs for full conversation content
3. **Tag**: Add project/tag metadata to all sessions for better searchability
4. **Archive**: Move completed sessions to cold storage, keep active ones hot
5. **Link**: Connect session artifacts to git commits and file changes
6. **Review**: Schedule weekly review of partial/abandoned sessions for revival
"""

with open(os.path.join(OUTPUT_DIR, 'EXECUTIVE_SUMMARY.md'), 'w', encoding='utf-8') as f:
    f.write(exec_md)
print("Generated EXECUTIVE_SUMMARY.md")

print("\n=== COMPLETE ===")
print(f"Reports generated in: {OUTPUT_DIR}")
print(f"Dashboard: {os.path.join(OUTPUT_DIR, 'DASHBOARD.html')}")
print(f"Master Index: {os.path.join(OUTPUT_DIR, 'MASTER_INDEX.md')}")
print(f"Executive Summary: {os.path.join(OUTPUT_DIR, 'EXECUTIVE_SUMMARY.md')}")

