+#!/usr/bin/env python3
+"""
+Generate dashboard and executive summary from existing master index.
+"""
+
+import json, os, re
+from datetime import datetime
+from collections import Counter
+
+OUTPUT_DIR = r'X:\SESSION_ARCHIVES\ALL_SESSIONS_DIRECTORY_VAULT\session_reports'
+INDEX_PATH = os.path.join(OUTPUT_DIR, 'MASTER_INDEX.json')
+
+with open(INDEX_PATH, 'r', encoding='utf-8') as f:
+    all_sessions = json.load(f)
+
+print(f"Loaded {len(all_sessions)} sessions from master index")
+
+# ============================================================
+# GENERATE REMAINING SESSION REPORTS (other tools)
+# ============================================================
+print("Generating remaining session reports...")
+for session in all_sessions:
+    if session['tool'] in ('charm-crush', 'claude-code', 'codex-cli', 'gemini-cli', 'kilo-code', 'opencode-desktop', 'session-archive'):
+        tool = session['tool']
+        sid = session['id']
+        safe_sid = re.sub(r'[^a-zA-Z0-9_-]', '_', sid)
+        report_path = os.path.join(OUTPUT_DIR, f'{tool}-{safe_sid}.md')
+        if not os.path.exists(report_path):
+            report = f"""# Session Report: {session['title']}
+
+## Metadata
+- **ID**: {sid}
+- **Tool**: {tool}
+- **Date**: {session.get('date', 'Unknown')}
+- **Status**: {session.get('status', 'Unknown')}
+- **Turns**: {session.get('turns_user', 0)} user / {session.get('turns_assistant', 0)} assistant
+
+## Summary
+{session.get('summary', 'No summary available.')}
+
+## Full Prompt / Objective
+{session.get('full_prompt', 'N/A')}
+
+## Status Assessment
+{session.get('status', 'Unknown')} - {session.get('recommendations', 'No recommendations.')}
+
+## Recommendations
+- {session.get('recommendations', 'Review session artifacts and document outcomes.')}
+
+## Tags
+{tool}, {session.get('status', 'unknown')}
+"""
+            with open(report_path, 'w', encoding='utf-8') as f:
+                f.write(report)
+
+print(f"Generated reports for non-antigravity sessions")
+
+# ============================================================
+# GENERATE EXECUTIVE SUMMARY
+# ============================================================
+print("Generating EXECUTIVE_SUMMARY.md...")
+
+by_tool = Counter(s['tool'] for s in all_sessions)
+by_status = Counter(s['status'] for s in all_sessions)
+by_date = Counter(s['date'] for s in all_sessions if s['date'] != 'Unknown')
+
+total_turns_user = sum(s.get('turns_user', 0) for s in all_sessions)
+total_turns_assistant = sum(s.get('turns_assistant', 0) for s in all_sessions)
+
+top_tools = by_tool.most_common(15)
+top_dates = sorted(by_date.items(), key=lambda x: -x[1])[:10]
+top_sessions = sorted(all_sessions, key=lambda s: -(s.get('turns_assistant',0) + s.get('turns_user',0)))[:20]
+
+exec_md = f"""# Executive Summary — All AI Session Audit
+
+**Generated**: {datetime.now().strftime('%Y-%m-%d %H:%M')}
+**Total Sessions Audited**: {len(all_sessions)}
+**Tools Covered**: {len(by_tool)}
+**Date Range**: {min(by_date.keys()) if by_date else 'N/A'} to {max(by_date.keys()) if by_date else 'N/A'}
