#!/usr/bin/env python3
"""
Generate dashboard and executive summary from existing master index.
"""

import json, os, re
from datetime import datetime
from collections import Counter

OUTPUT_DIR = r'X:\SESSION_ARCHIVES\ALL_SESSIONS_DIRECTORY_VAULT\session_reports'
INDEX_PATH = os.path.join(OUTPUT_DIR, 'MASTER_INDEX.json')

print("Loading master index...")
with open(INDEX_PATH, 'r', encoding='utf-8') as f:
    all_sessions = json.load(f)

print(f"Loaded {len(all_sessions)} sessions")

by_tool = Counter(s['tool'] for s in all_sessions)
by_status = Counter(s['status'] for s in all_sessions)
by_date = Counter(s['date'] for s in all_sessions if s['date'] != 'Unknown')

total_turns_user = sum(s.get('turns_user', 0) for s in all_sessions)
total_turns_assistant = sum(s.get('turns_assistant', 0) for s in all_sessions)

# ============================================================
# GENERATE EXECUTIVE SUMMARY
# ============================================================
print("Generating EXECUTIVE_SUMMARY.md...")

top_tools = by_tool.most_common(15)
top_dates = sorted(by_date.items(), key=lambda x: -x[1])[:10]
top_sessions = sorted(all_sessions, key=lambda s: -(s.get('turns_assistant',0) + s.get('turns_user',0)))[:20]

exec_md = f"""# Executive Summary — All AI Session Audit

**Generated**: {datetime.now().strftime('%Y-%m-%d %H:%M')}
**Total Sessions Audited**: {len(all_sessions)}
**Tools Covered**: {len(by_tool)}
**Date Range**: {min(by_date.keys()) if by_date else 'N/A'} to {max(by_date.keys()) if by_date else 'N/A'}

## Key Findings

### 1. Tool Usage Distribution
"""
for tool, count in top_tools:
    exec_md += f"- **{tool}**: {count} sessions ({count/len(all_sessions)*100:.1f}%)\n"

exec_md += f"""
### 2. Status Breakdown
"""
for status, count in sorted(by_status.items(), key=lambda x: -x[1]):
    exec_md += f"- **{status}**: {count} ({count/len(all_sessions)*100:.1f}%)\n"

exec_md += f"""
### 3. Activity Peaks
"""
for date, count in top_dates:
    exec_md += f"- {date}: {count} sessions\n"

exec_md += f"""
### 4. Most Active Sessions (by turn count)
"""
for s in top_sessions[:10]:
    exec_md += f"- [{s['tool']}] {s['title'][:70]} - {s.get('turns_user',0)}u/{s.get('turns_assistant',0)}a ({s['date']})\n"

exec_md += f"""
### 5. Recurring Themes
- "Review and advise" pattern dominates across all tools
- Crypto trading platform development (multiple attempts)
- Dashboard creation and system integration
- "Proceed all" / automation loops
- Revenue generation and business valuation focus
- Multi-agent orchestration (FOOTCLAN, AI Army)
- Hardware optimization (RTX 4060 8GB)
- Music video / media generation pipelines

### 6. Data Gaps & Limitations
- Charm Crush: 1325 sessions but limited metadata extraction
- Gemini: 76 DB files but protobuf content not fully decoded
- OpenCode: Workspace files found but prompt history not extracted
- Qwen/FreeBuff: 111 log files but format requires specialized parsing
- Claude: 745 history entries but only first 100 processed

### 7. Recommendations
1. **Consolidate**: Merge duplicate sessions across tools into unified project timelines
2. **Extract**: Deep-parse Charm Crush and Gemini DBs for full conversation content
3. **Tag**: Add project/tag metadata to all sessions for better searchability
4. **Archive**: Move completed sessions to cold storage, keep active ones hot
5. **Link**: Connect session artifacts to git commits and file changes
6. **Review**: Schedule weekly review of partial/abandoned sessions for revival

## Session Counts by Tool
| Tool | Count |
|------|-------|
"""
for tool, count in sorted(by_tool.items(), key=lambda x: -x[1]):
    exec_md += f"| {tool} | {count} |\n"

with open(os.path.join(OUTPUT_DIR, 'EXECUTIVE_SUMMARY.md'), 'w', encoding='utf-8') as f:
    f.write(exec_md)
print("Generated EXECUTIVE_SUMMARY.md")

