#!/usr/bin/env python3
import os, re, json, sys
from datetime import datetime
from collections import Counter

sys.stdout.reconfigure(encoding='utf-8')
OUTPUT_DIR = r'X:\SESSION_ARCHIVES\ALL_SESSIONS_DIRECTORY_VAULT\session_reports'
DASHBOARD_PATH = os.path.join(OUTPUT_DIR, 'DASHBOARD.html')

def parse_report(fname):
    fpath = os.path.join(OUTPUT_DIR, fname)
    with open(fpath, 'r', encoding='utf-8') as f:
        content = f.read()

    sid = fname.replace('.md', '')
    tool = 'unknown'
    if '-' in fname:
        tool = fname.split('-')[0]

    title = 'Untitled'
    for line in content.splitlines():
        if line.startswith('# Session Report: '):
            title = line.replace('# Session Report: ', '').strip()
            break

    date = 'Unknown'
    for line in content.splitlines():
        if line.startswith('- **Date**: '):
            date = line.replace('- **Date**: ', '').strip()
            break

    status = 'Unknown'
    for line in content.splitlines():
        if line.startswith('- **Status**: '):
            status = line.replace('- **Status**: ', '').strip()
            break

    turns_user = 0
    turns_assistant = 0
    for line in content.splitlines():
        if line.startswith('- **Turns**: '):
            turns_text = line.replace('- **Turns**: ', '').strip()
            parts = turns_text.split(' user / ')
            if len(parts) == 2:
                turns_user = int(parts[0])
                turns_assistant = int(parts[1].replace(' assistant', ''))
            break

    summary = ''
    try:
        summary = content.split('## Summary\n', 1)[1].split('\n## ', 1)[0].strip()
    except Exception:
        pass

    full_prompt = ''
    try:
        full_prompt = content.split('## Full Prompt / Objective\n', 1)[1].split('\n## ', 1)[0].strip()
    except Exception:
        pass

    return {
        'id': sid,
        'tool': tool,
        'date': date,
        'timestamp': date,
        'title': title,
        'full_prompt': full_prompt,
        'summary': summary,
        'status': status,
        'turns_user': turns_user,
        'turns_assistant': turns_assistant,
        'report_url': fname,
        'artifacts': [],
        'folder': '',
        'user_messages': []
    }

print("Scanning reports...")
sessions = []
for fname in os.listdir(OUTPUT_DIR):
    if not fname.endswith('.md') or fname in ['MASTER_INDEX.md', 'EXECUTIVE_SUMMARY.md', 'RECREATION_GUIDE.md']:
        continue
    try:
        sessions.append(parse_report(fname))
    except Exception as e:
        print(f"Error parsing {fname}: {e}")

print(f"Parsed {len(sessions)} sessions")

# Sort by date descending
sessions.sort(key=lambda s: s['date'], reverse=True)

# Generate dashboard
sessions_json = json.dumps(sessions, ensure_ascii=False)

dashboard_html = f'''<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>AI Session Dashboard</title>
<style>
* {{ margin: 0; padding: 0; box-sizing: border-box; }}
body {{
  font-family: 'Segoe UI', system-ui, sans-serif;
  background: #0f0f1a;
  color: #e0e0e0;
  min-height: 100vh;
}}
.header {{
  background: linear-gradient(135deg, #1a1a2e 0%, #16213e 100%);
  padding: 24px;
  border-bottom: 1px solid #2a2a4a;
}}
.header h1 {{
  font-size: 28px;
  font-weight: 700;
  background: linear-gradient(90deg, #00d4ff, #7b2fff);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  margin-bottom: 8px;
}}
.header p {{ color: #888; font-size: 14px; }}
.stats-grid {{
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 16px;
  padding: 24px;
}}
.stat-card {{
  background: #1a1a2e;
  border: 1px solid #2a2a4a;
  border-radius: 12px;
  padding: 20px;
  text-align: center;
  transition: transform 0.2s;
}}
.stat-card:hover {{ transform: translateY(-2px); }}
.stat-value {{
  font-size: 32px;
  font-weight: 700;
  background: linear-gradient(90deg, #00d4ff, #7b2fff);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}}
.stat-label {{
  color: #888;
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 1px;
  margin-top: 4px;
}}
.controls {{
  padding: 0 24px 24px;
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
  align-items: center;
}}
.controls input, .controls select {{
  background: #1a1a2e;
  border: 1px solid #2a2a4a;
  color: #e0e0e0;
  padding: 10px 16px;
  border-radius: 8px;
  font-size: 14px;
}}
.controls input {{ flex: 1; min-width: 200px; }}
.filter-btn {{
  background: #2a2a4a;
  border: 1px solid #3a3a5a;
  color: #e0e0e0;
  padding: 8px 16px;
  border-radius: 6px;
  cursor: pointer;
  font-size: 13px;
  transition: all 0.2s;
}}
.filter-btn:hover {{ background: #3a3a5a; }}
.table-container {{
  padding: 0 24px 24px;
  overflow-x: auto;
}}
table {{
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
}}
th {{
  background: #1a1a2e;
  color: #00d4ff;
  padding: 12px;
  text-align: left;
  cursor: pointer;
  border-bottom: 2px solid #2a2a4a;
  white-space: nowrap;
}}
th:hover {{ color: #fff; }}
td {{
  padding: 10px 12px;
  border-bottom: 1px solid #1a1a2e;
  vertical-align: top;
}}
tr:hover {{ background: #1a1a2e; }}
.status-badge {{
  display: inline-block;
  padding: 4px 8px;
  border-radius: 4px;
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
}}
.status-completed {{ background: #1a3a2a; color: #4ade80; }}
.status-partial {{ background: #3a3a1a; color: #facc15; }}
.status-abandoned {{ background: #3a1a1a; color: #f87171; }}
.status-ongoing {{ background: #1a2a3a; color: #60a5fa; }}
.tool-tag {{
  display: inline-block;
  padding: 2px 8px;
  border-radius: 4px;
  font-size: 11px;
  background: #2a2a4a;
  color: #aaa;
  margin-right: 4px;
}}
.expand-btn {{
  background: none;
  border: none;
  color: #00d4ff;
  cursor: pointer;
  font-size: 12px;
}}
.expand-btn:hover {{ text-decoration: underline; }}
.title-link {{
  color: #e0e0e0;
  text-decoration: none;
  cursor: pointer;
}}
.title-link:hover {{ color: #fff; text-decoration: underline; }}
.detail-row {{ display: none; background: #151525; }}
.detail-row.show {{ display: table-row; }}
.detail-cell {{
  padding: 16px;
  border-bottom: 1px solid #2a2a4a;
}}
.detail-section {{ margin-bottom: 12px; }}
.detail-section h4 {{
  color: #7b2fff;
  font-size: 12px;
  text-transform: uppercase;
  margin-bottom: 4px;
}}
.detail-section p {{ color: #aaa; font-size: 13px; line-height: 1.5; }}
.report-link {{
  display: inline-block;
  margin-top: 12px;
  padding: 8px 16px;
  background: #2a2a4a;
  border: 1px solid #3a3a5a;
  color: #e0e0e0;
  text-decoration: none;
  border-radius: 6px;
  font-size: 13px;
}}
.report-link:hover {{ background: #3a3a5a; color: #fff; }}
</style>
</head>
<body>
<div class="header">
  <h1>AI Session Dashboard</h1>
  <p>Comprehensive audit across all AI coding tools, IDEs, and agents</p>
</div>

<div class="stats-grid">
  <div class="stat-card">
    <div class="stat-value" id="total-sessions">0</div>
    <div class="stat-label">Total Sessions</div>
  </div>
  <div class="stat-card">
    <div class="stat-value" id="total-tools">0</div>
    <div class="stat-label">Tools</div>
  </div>
  <div class="stat-card">
    <div class="stat-value" id="completed-count">0</div>
    <div class="stat-label">Completed</div>
  </div>
  <div class="stat-card">
    <div class="stat-value" id="partial-count">0</div>
    <div class="stat-label">Partial</div>
  </div>
  <div class="stat-card">
    <div class="stat-value" id="abandoned-count">0</div>
    <div class="stat-label">Abandoned</div>
  </div>
  <div class="stat-card">
    <div class="stat-value" id="total-turns">0</div>
    <div class="stat-label">Total Turns</div>
  </div>
</div>

<div class="controls">
  <input type="text" id="searchInput" placeholder="Search sessions...">
  <select id="toolFilter">
    <option value="all">All Tools</option>
  </select>
  <select id="statusFilter">
    <option value="all">All Status</option>
    <option value="Completed">Completed</option>
    <option value="Partial">Partial</option>
    <option value="Abandoned">Abandoned</option>
    <option value="Ongoing">Ongoing</option>
  </select>
  <button class="filter-btn" onclick="exportCSV()">Export CSV</button>
</div>

<div class="table-container">
  <table id="sessionTable">
    <thead>
      <tr>
        <th onclick="sortBy('id')">ID</th>
        <th onclick="sortBy('tool')">Tool</th>
        <th onclick="sortBy('date')">Date</th>
        <th onclick="sortBy('title')">Title</th>
        <th onclick="sortBy('status')">Status</th>
        <th onclick="sortBy('turns')">Turns</th>
        <th>Actions</th>
      </tr>
    </thead>
    <tbody id="sessionTableBody">
    </tbody>
  </table>
</div>

<script>
const sessions = {sessions_json};
let currentSort = {{ field: 'date', asc: false }};
let filteredSessions = [...sessions];

function init() {{
  const tools = [...new Set(sessions.map(s => s.tool))].sort();
  const toolFilter = document.getElementById('toolFilter');
  tools.forEach(tool => {{
    const opt = document.createElement('option');
    opt.value = tool;
    opt.textContent = tool;
    toolFilter.appendChild(opt);
  }});

  updateStats();
  renderTable();
}}

function updateStats() {{
  document.getElementById('total-sessions').textContent = sessions.length;
  const tools = new Set(sessions.map(s => s.tool));
  document.getElementById('total-tools').textContent = tools.size;
  document.getElementById('completed-count').textContent = sessions.filter(s => s.status === 'Completed').length;
  document.getElementById('partial-count').textContent = sessions.filter(s => s.status === 'Partial').length;
  document.getElementById('abandoned-count').textContent = sessions.filter(s => s.status === 'Abandoned').length;
  const totalTurns = sessions.reduce((sum, s) => sum + (s.turns_user||0) + (s.turns_assistant||0), 0);
  document.getElementById('total-turns').textContent = totalTurns.toLocaleString();
}}

function renderTable() {{
  const tbody = document.getElementById('sessionTableBody');
  const search = document.getElementById('searchInput').value.toLowerCase();
  const toolFilter = document.getElementById('toolFilter').value;
  const statusFilter = document.getElementById('statusFilter').value;

  filteredSessions = sessions.filter(s => {{
    const matchSearch = !search || 
      s.title.toLowerCase().includes(search) ||
      s.id.toLowerCase().includes(search) ||
      (s.full_prompt && s.full_prompt.toLowerCase().includes(search)) ||
      (s.summary && s.summary.toLowerCase().includes(search));
    const matchTool = toolFilter === 'all' || s.tool === toolFilter;
    const matchStatus = statusFilter === 'all' || s.status === statusFilter;
    return matchSearch && matchTool && matchStatus;
  }});

  filteredSessions.sort((a, b) => {{
    let aVal = a[currentSort.field] || '';
    let bVal = b[currentSort.field] || '';
    if (currentSort.field === 'turns') {{
      aVal = (a.turns_user||0) + (a.turns_assistant||0);
      bVal = (b.turns_user||0) + (b.turns_assistant||0);
    }}
    if (aVal < bVal) return currentSort.asc ? -1 : 1;
    if (aVal > bVal) return currentSort.asc ? 1 : -1;
    return 0;
  }});

  tbody.innerHTML = filteredSessions.map((s, i) => {{
    const statusClass = 'status-' + s.status.toLowerCase();
    const dateStr = s.date ? s.date.substring(0, 10) : 'Unknown';
    const reportUrl = escapeHtml(s.report_url || '');
    return `
      <tr>
        <td><code style="color:#666;font-size:11px;">${{s.id.substring(0,12)}}</code></td>
        <td><span class="tool-tag">${{s.tool}}</span></td>
        <td>${{dateStr}}</td>
        <td>
          <a class="title-link" href="${{reportUrl}}" target="_blank" rel="noopener" title="${{escapeHtml(s.title)}}">
            ${{escapeHtml(s.title.substring(0, 70))}}${{s.title.length > 70 ? '...' : ''}}
          </a>
        </td>
        <td><span class="status-badge ${{statusClass}}">${{s.status}}</span></td>
        <td>${{s.turns_user||0}}u/${{s.turns_assistant||0}}a</td>
        <td>
          <button class="expand-btn" onclick="toggleDetail(${{i}})">Expand</button>
        </td>
      </tr>
      <tr class="detail-row" id="detail-${{i}}">
        <td colspan="7" class="detail-cell">
          <div class="detail-section">
            <h4>Full Prompt</h4>
            <p>${{escapeHtml(s.full_prompt || 'N/A')}}</p>
          </div>
          <div class="detail-section">
            <h4>Summary</h4>
            <p>${{escapeHtml(s.summary || 'No summary')}}</p>
          </div>
          <div class="detail-section">
            <h4>Recommendations</h4>
            <p>${{escapeHtml(s.recommendations || 'No recommendations')}}</p>
          </div>
          <a class="report-link" href="${{reportUrl}}" target="_blank" rel="noopener">Open Full Report</a>
        </td>
      </tr>
    `;
  }}).join('');
}}

function toggleDetail(index) {{
  const row = document.getElementById('detail-' + index);
  row.classList.toggle('show');
}}

function escapeHtml(text) {{
  if (!text) return '';
  const div = document.createElement('div');
  div.textContent = text;
  return div.innerHTML;
}}

function sortBy(field) {{
  if (currentSort.field === field) {{
    currentSort.asc = !currentSort.asc;
  }} else {{
    currentSort.field = field;
    currentSort.asc = true;
  }}
  renderTable();
}}

function exportCSV() {{
  let csv = 'ID,Tool,Date,Title,Status,Turns User,Turns Assistant,Recommendations\\n';
  filteredSessions.forEach(s => {{
    csv += `"${{s.id}}","${{s.tool}}","${{s.date}}","${{s.title.replace(/"/g, '""')}}","${{s.status}}",${{s.turns_user||0}},${{s.turns_assistant||0}},"${{(s.recommendations||'').replace(/"/g, '""')}}"\\n`;
  }});
  const blob = new Blob([csv], {{ type: 'text/csv' }});
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = 'session_export.csv';
  a.click();
}}

document.getElementById('searchInput').addEventListener('input', renderTable);
document.getElementById('toolFilter').addEventListener('change', renderTable);
document.getElementById('statusFilter').addEventListener('change', renderTable);

init();
</script>
</body>
</html>'''

with open(DASHBOARD_PATH, 'w', encoding='utf-8') as f:
    f.write(dashboard_html)

print(f"Dashboard rebuilt: {DASHBOARD_PATH}")
print(f"Total sessions: {len(sessions)}")

