#!/usr/bin/env python3
import os, sys, json
from collections import Counter, defaultdict
from datetime import datetime

sys.stdout.reconfigure(encoding='utf-8')
OUTPUT_DIR = r'X:\SESSION_ARCHIVES\ALL_SESSIONS_DIRECTORY_VAULT\session_reports'
DASHBOARD_PATH = os.path.join(OUTPUT_DIR, 'DASHBOARD.html')

print("Loading enriched index...", flush=True)
with open(os.path.join(OUTPUT_DIR, 'MASTER_INDEX.json'), 'r', encoding='utf-8') as f:
    sessions = json.load(f)
print(f"Loaded {len(sessions)} sessions", flush=True)

# Pre-compute stats
by_tool = Counter(s['tool'].split('-')[0] for s in sessions)
# Better tool normalization
def norm_tool(t):
    if t.startswith('antigravity'):
        return 'antigravity'
    elif t.startswith('charm'):
        return 'charm'
    return t
tool_counts = Counter(norm_tool(s['tool']) for s in sessions)
status_counts = Counter(s['status'] for s in sessions)
tag_counts = Counter()
for s in sessions:
    for t in s.get('tags', []):
        tag_counts[t] += 1

# Per-tool stats
tool_stats = defaultdict(lambda: {'total': 0, 'completed': 0, 'turns': 0})
for s in sessions:
    t = norm_tool(s['tool'])
    tool_stats[t]['total'] += 1
    if s['status'] == 'Completed':
        tool_stats[t]['completed'] += 1
    tool_stats[t]['turns'] += s.get('turns_user', 0) + s.get('turns_assistant', 0)

# Date histogram
date_counts = Counter()
for s in sessions:
    d = s.get('date', '')
    if d and d != 'Unknown' and len(d) >= 10:
        date_counts[d[:10]] += 1
# Top 14 days for chart
top_dates = sorted(date_counts.items(), key=lambda x: -x[1])[:14]
max_count = max(c for _, c in top_dates) if top_dates else 1

# Build sessions JSON (compact, without huge conversation arrays)
compact_sessions = []
for s in sessions:
    compact_sessions.append({
        'id': s['id'],
        'tool': s['tool'],
        'tool_norm': norm_tool(s['tool']),
        'date': s['date'],
        'title': s['title'],
        'full_prompt': s.get('full_prompt', '')[:500],
        'summary': s.get('summary', '')[:300],
        'status': s['status'],
        'turns_user': s.get('turns_user', 0),
        'turns_assistant': s.get('turns_assistant', 0),
        'report_url': f"{s['tool']}-{s['id']}.md",
        'folder': s.get('folder', ''),
        'tags': s.get('tags', []),
        'has_full_content': s.get('has_full_content', False),
        'total_chars': s.get('total_chars', 0),
        'models': s.get('models', []),
        'providers': s.get('providers', []),
        'recommendations': s.get('recommendations', '')[:300]
    })

sessions_json = json.dumps(compact_sessions, ensure_ascii=False)
tool_stats_json = json.dumps(dict(tool_stats), ensure_ascii=False)
tag_counts_json = json.dumps(dict(tag_counts), ensure_ascii=False)
top_dates_json = json.dumps(top_dates, ensure_ascii=False)
status_counts_json = json.dumps(dict(status_counts), ensure_ascii=False)

print(f"Building dashboard HTML...", flush=True)

